package com.projexa.coaching.reports.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/reports") public class ReportsController {private final JdbcTemplate db;public ReportsController(JdbcTemplate db){this.db=db;}
 @GetMapping("/dashboard") @PreAuthorize("hasAnyAuthority('reports.read','dashboard.read')") public Map<String,Object> dashboard(){UUID t=TenantContextHolder.getRequired();Map<String,Object> students=db.queryForMap("select count(*) total, count(*) filter(where status='ACTIVE') active from students where tenant_id=?",t);Map<String,Object> fees=db.queryForMap("select coalesce(sum(amount),0) billed,coalesce(sum(paid_amount),0) collected,coalesce(sum(amount-paid_amount),0) outstanding from invoices where tenant_id=?",t);Map<String,Object> leads=db.queryForMap("select count(*) total,count(*) filter(where stage='ADMISSION') converted from leads where tenant_id=?",t);return Map.of("students",students,"fees",fees,"admissions",leads);}
 @GetMapping("/attendance") @PreAuthorize("hasAuthority('reports.read')") public List<Map<String,Object>> attendance(){return db.queryForList("select s.id,s.admission_number,s.first_name,s.last_name,coalesce(sum(case when ar.status='PRESENT' then 1 else 0 end),0) present,count(ar.id) total from students s left join attendance_records ar on ar.student_id=s.id and ar.tenant_id=s.tenant_id where s.tenant_id=? group by s.id order by s.first_name",TenantContextHolder.getRequired());}
}
